<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: #f4f6f8;
      color: #17202a;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 24px;
    }

    main {
      width: min(900px, 100%);
      margin: 0 auto;
    }

    h1, h2 {
      margin-top: 0;
    }

    .panel {
      margin-bottom: 20px;
      padding: 20px;
      border: 1px solid #d9dee5;
      border-radius: 10px;
      background: #fff;
      box-shadow: 0 2px 8px rgb(0 0 0 / 5%);
    }

    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 14px;
      align-items: end;
    }

    label {
      display: grid;
      gap: 6px;
      font-weight: 600;
    }

    input, select, button {
      min-height: 42px;
      padding: 9px 11px;
      border: 1px solid #aeb7c2;
      border-radius: 6px;
      font: inherit;
    }

    input:focus, select:focus, button:focus {
      outline: 3px solid rgb(36 105 186 / 20%);
      border-color: #2469ba;
    }

    button {
      border-color: #2469ba;
      background: #2469ba;
      color: #fff;
      font-weight: 700;
      cursor: pointer;
    }

    button:hover {
      background: #1b5598;
    }

    #form-error {
      min-height: 1.5em;
      margin: 12px 0 0;
      color: #b42318;
      font-weight: 600;
    }

    .summary {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
      gap: 12px;
    }

    .summary-card {
      padding: 14px;
      border-radius: 8px;
      background: #edf4fc;
    }

    .summary-card strong {
      display: block;
      margin-top: 4px;
      font-size: 1.25rem;
    }

    #total {
      font-size: 1.5rem;
    }

    #expense-list {
      display: grid;
      gap: 10px;
    }

    .expense {
      display: grid;
      grid-template-columns: minmax(90px, 1fr) minmax(110px, 1fr) minmax(120px, 1fr) 2fr auto;
      gap: 12px;
      align-items: center;
      padding: 12px;
      border: 1px solid #d9dee5;
      border-radius: 8px;
      background: #fff;
    }

    .expense[hidden] {
      display: none;
    }

    .expense-amount {
      font-weight: 800;
    }

    .expense-category {
      text-transform: capitalize;
    }

    .expense-note {
      color: #59636e;
      overflow-wrap: anywhere;
    }

    .exp-del {
      min-height: 36px;
      padding: 7px 11px;
      border-color: #b42318;
      background: #b42318;
    }

    .exp-del:hover {
      background: #8f1c13;
    }

    #empty-message {
      margin: 0;
      padding: 18px;
      text-align: center;
      color: #59636e;
    }

    @media (max-width: 650px) {
      body {
        padding: 12px;
      }

      .panel {
        padding: 15px;
      }

      .expense {
        grid-template-columns: 1fr 1fr;
      }

      .expense-note {
        grid-column: 1 / -1;
      }

      .exp-del {
        justify-self: start;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section class="panel" aria-labelledby="entry-heading">
      <h2 id="entry-heading">Add expense</h2>
      <form id="expense-form" novalidate>
        <div class="grid">
          <label>
            Amount
            <input id="amount" name="amount" type="number" min="0.01" step="0.01" placeholder="0.00">
          </label>

          <label>
            Category
            <select id="category" name="category">
              <option value="groceries">Groceries</option>
              <option value="transport">Transport</option>
              <option value="bills">Bills</option>
              <option value="fun">Fun</option>
            </select>
          </label>

          <label>
            Date
            <input id="date" name="date" type="date">
          </label>

          <label>
            Note (optional)
            <input id="note" name="note" type="text" maxlength="200" placeholder="What was it for?">
          </label>

          <button id="add-expense" type="submit">Add expense</button>
        </div>
        <p id="form-error" role="alert" aria-live="polite"></p>
      </form>
    </section>

    <section class="panel" aria-labelledby="filter-heading">
      <h2 id="filter-heading">Filters</h2>
      <div class="grid">
        <label>
          Category
          <select id="filter-category">
            <option value="all">All</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          From
          <input id="filter-from" type="date">
        </label>

        <label>
          To
          <input id="filter-to" type="date">
        </label>
      </div>
    </section>

    <section class="panel" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Visible summary</h2>
      <div class="summary">
        <div class="summary-card">
          Total
          <strong id="total">0.00</strong>
        </div>
        <div class="summary-card cat-total" data-cat="groceries">Groceries: 0.00</div>
        <div class="summary-card cat-total" data-cat="transport">Transport: 0.00</div>
        <div class="summary-card cat-total" data-cat="bills">Bills: 0.00</div>
        <div class="summary-card cat-total" data-cat="fun">Fun: 0.00</div>
      </div>
    </section>

    <section aria-labelledby="list-heading">
      <h2 id="list-heading">Expenses</h2>
      <div id="expense-list"></div>
      <p id="empty-message">No expenses yet.</p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const categories = ["groceries", "transport", "bills", "fun"];
      const storageKey = "personal-expense-tracker-expenses";

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const errorElement = document.getElementById("form-error");
      const listElement = document.getElementById("expense-list");
      const emptyMessage = document.getElementById("empty-message");
      const totalElement = document.getElementById("total");
      const categoryFilter = document.getElementById("filter-category");
      const fromFilter = document.getElementById("filter-from");
      const toFilter = document.getElementById("filter-to");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const parsed = JSON.parse(localStorage.getItem(storageKey) || "[]");
          if (!Array.isArray(parsed)) return [];

          return parsed.filter(expense =>
            expense &&
            Number.isFinite(Number(expense.amount)) &&
            Number(expense.amount) > 0 &&
            categories.includes(expense.category) &&
            typeof expense.date === "string" &&
            expense.date
          ).map(expense => ({
            id: String(expense.id),
            amount: Number(expense.amount),
            category: expense.category,
            date: expense.date,
            note: typeof expense.note === "string" ? expense.note : ""
          }));
        } catch {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(storageKey, JSON.stringify(expenses));
      }

      function formatAmount(value) {
        return Number(value).toFixed(2);
      }

      function isVisible(expense) {
        const selectedCategory = categoryFilter.value;
        const from = fromFilter.value;
        const to = toFilter.value;

        return (selectedCategory === "all" || expense.category === selectedCategory) &&
          (!from || expense.date >= from) &&
          (!to || expense.date <= to);
      }

      function render() {
        listElement.replaceChildren();

        const totals = Object.fromEntries(categories.map(category => [category, 0]));
        let visibleTotal = 0;
        let visibleCount = 0;

        expenses.forEach(expense => {
          const row = document.createElement("div");
          row.className = "expense";
          row.dataset.id = expense.id;

          const amount = document.createElement("span");
          amount.className = "expense-amount";
          amount.textContent = "$" + formatAmount(expense.amount);

          const category = document.createElement("span");
          category.className = "expense-category";
          category.textContent = expense.category;

          const date = document.createElement("time");
          date.dateTime = expense.date;
          date.textContent = expense.date;

          const note = document.createElement("span");
          note.className = "expense-note";
          note.textContent = expense.note || "—";

          const deleteButton = document.createElement("button");
          deleteButton.type = "button";
          deleteButton.className = "exp-del";
          deleteButton.textContent = "Delete";
          deleteButton.setAttribute("aria-label", "Delete expense");

          const visible = isVisible(expense);
          row.hidden = !visible;

          if (visible) {
            visibleCount++;
            visibleTotal += expense.amount;
            totals[expense.category] += expense.amount;
          }

          row.append(amount, category, date, note, deleteButton);
          listElement.append(row);
        });

        totalElement.textContent = formatAmount(visibleTotal);

        document.querySelectorAll(".cat-total").forEach(element => {
          const category = element.dataset.cat;
          const label = category.charAt(0).toUpperCase() + category.slice(1);
          element.textContent = label + ": " + formatAmount(totals[category]);
        });

        emptyMessage.hidden = visibleCount > 0;
        emptyMessage.textContent = expenses.length
          ? "No expenses match the current filters."
          : "No expenses yet.";
      }

      form.addEventListener("submit", event => {
        event.preventDefault();

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const date = dateInput.value;

        if (rawAmount === "" || !Number.isFinite(amount) || amount <= 0) {
          errorElement.textContent = "Enter an amount greater than zero.";
          return;
        }

        if (!date) {
          errorElement.textContent = "Choose a date.";
          return;
        }

        expenses.unshift({
          id: Date.now().toString(36) + Math.random().toString(36).slice(2),
          amount,
          category: categoryInput.value,
          date,
          note: noteInput.value.trim()
        });

        saveExpenses();
        errorElement.textContent = "";
        amountInput.value = "";
        noteInput.value = "";
        render();
        amountInput.focus();
      });

      listElement.addEventListener("click", event => {
        const button = event.target.closest(".exp-del");
        if (!button) return;

        const row = button.closest(".expense");
        expenses = expenses.filter(expense => expense.id !== row.dataset.id);
        saveExpenses();
        render();
      });

      [categoryFilter, fromFilter, toFilter].forEach(control => {
        control.addEventListener("change", render);
        control.addEventListener("input", render);
      });

      render();
    })();
  </script>
</body>
</html>
